import React, {useState, useEffect} from 'react';
import {Calendar, Clock, AlertCircle, CheckCircle, Trash2, User} from 'lucide-react'; // 1. Added User icon
import {tasksAPI, Task} from '../services/api';
import '../styles/TaskList.css';
import TaskDetailModal from './TaskDetailModal';

interface TaskListProps {
    isAdmin?: boolean
}

const TaskList: React.FC = ({isAdmin}: TaskListProps) => {
    const [tasks, setTasks] = useState<Task[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [filter, setFilter] = useState<'all' | 'pending' | 'completed'>('all');
    const [selectedTask, setSelectedTask] = useState<Task | null>(null);

    useEffect(() => {
        fetchTasks();
    }, []);

    const fetchTasks = async () => {
        try {
            setLoading(true);
            const userString = localStorage.getItem('user');
            const user = userString ? JSON.parse(userString) : null;
            const activeTeamId = user?.teamId;

            const data = await tasksAPI.getMyTasks(activeTeamId);
            setTasks(data);
            setError(null);
        } catch (err: any) {
            setError('Failed to load tasks');
        } finally {
            setLoading(false);
        }
    };

    const formatDate = (dateString: string) => {
        if (!dateString) return 'N/A';
        const date = new Date(dateString);
        return date.toLocaleDateString('en-US', {month: 'short', day: 'numeric', year: 'numeric'});
    };

    const getPriorityColor = (priority: string) => {
        switch (priority.toUpperCase()) {
            case 'HIGH':
                return 'yellow';
            case 'MEDIUM':
                return 'blue';
            case 'LOW':
                return 'white';
            default:
                return 'red';
        }
    };

    const getStatusIcon = (status: string) => {
        switch (status.toUpperCase()) {
            case 'COMPLETED':
                return <CheckCircle size={20} color="#4caf50"/>;
            case 'IN_PROGRESS':
                return <Clock size={20} color="#2196f3"/>;
            case 'TODO':
                return <AlertCircle size={20} color="#ff9800"/>;
            default:
                return <AlertCircle size={20} color="#999"/>;
        }
    };

    const isOverdue = (dueDate: string, status: string) => {
        if (status.toUpperCase() === 'COMPLETED') return false;
        if (!dueDate) return false;
        return new Date(dueDate) < new Date();
    };

    const handleDeleteTask = async (taskId: number) => {
        if (!window.confirm("Delete this task?")) return;
        try {
            await tasksAPI.deleteTask(taskId);
            fetchTasks();
        } catch (err) {
            console.error("Failed to delete task", err);
        }
    };

    // Helper to render the assignee info
    const renderAssignee = (task: Task) => (
        <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: '6px',
            fontSize: '13px',
            color: '#666',
            marginBottom: '8px'
        }}>
            <User size={14}/>
            {task.assignedUserName ? (
                <span>Assigned to <strong style={{color: '#4a9eff'}}>{task.assignedUserName}</strong></span>
            ) : (
                <span style={{fontStyle: 'italic', color: '#999'}}>Unassigned</span>
            )}
        </div>
    );

    const filteredTasks = tasks.filter((task) => {
        if (filter === 'completed') return task.status.toUpperCase() === 'COMPLETED';
        if (filter === 'pending') return task.status.toUpperCase() !== 'COMPLETED';
        return true;
    });

    const pendingTasks = tasks.filter(t => t.status.toUpperCase() !== 'COMPLETED');
    const completedTasks = tasks.filter(t => t.status.toUpperCase() === 'COMPLETED');

    return (
        <div className="task-list-container">
            <div className="task-list-header">
                <h2>My Tasks</h2>
                <div className="task-filters">
                    <button className={`filter-btn ${filter === 'all' ? 'active' : ''}`}
                            onClick={() => setFilter('all')}>All ({tasks.length})
                    </button>
                    <button className={`filter-btn ${filter === 'pending' ? 'active' : ''}`}
                            onClick={() => setFilter('pending')}>Pending ({pendingTasks.length})
                    </button>
                    <button className={`filter-btn ${filter === 'completed' ? 'active' : ''}`}
                            onClick={() => setFilter('completed')}>Completed ({completedTasks.length})
                    </button>
                </div>
            </div>

            {loading && <div className="loading-message">Loading tasks...</div>}
            {error && <div className="error-message">{error}</div>}

            {!loading && !error && filteredTasks.length === 0 && (
                <div className="no-tasks-message">No tasks found.</div>
            )}

            {filter === 'all' ? (
                <>
                    <h3 style={{margin: '16px 0 8px', color: '#1a1a1a'}}>Pending</h3>
                    <div className="tasks-grid">
                        {pendingTasks.map((task) => (
                            <div key={task.id}
                                 className={`task-card ${isOverdue(task.dueDate, task.status) ? 'overdue' : ''}`}
                                 onClick={() => setSelectedTask(task)} style={{cursor: 'pointer'}}>
                                <div className="task-card-header">
                                    <div className="task-status-icon">{getStatusIcon(task.status)}</div>
                                    <div style={{display: 'flex', gap: '8px', alignItems: 'center'}}>
                                        <span className="task-priority"
                                              style={{backgroundColor: getPriorityColor(task.priority)}}>{task.priority}</span>
                                        <button onClick={(e) => {
                                            e.stopPropagation();
                                            handleDeleteTask(task.id);
                                        }} className="delete-task-btn" style={{
                                            background: 'none',
                                            border: 'none',
                                            cursor: 'pointer',
                                            color: '#999',
                                            padding: 0
                                        }}><Trash2 size={16}/></button>
                                    </div>
                                </div>

                                <h3 className="task-title">{task.taskName}</h3>
                                <p className="task-description">{task.description || 'No description'}</p>

                                {/* 2. SHOW ASSIGNEE */}
                                {renderAssignee(task)}

                                <div className="task-dates">
                                    <div className="date-item">
                                        <Calendar size={16}/>
                                        <div className="date-info"><span className="date-label">Start Date</span><span
                                            className="date-value">{formatDate(task.startDate)}</span></div>
                                    </div>
                                    <div className="date-item">
                                        <Clock size={16}/>
                                        <div className="date-info"><span className="date-label">Deadline</span><span
                                            className={`date-value ${isOverdue(task.dueDate, task.status) ? 'overdue-text' : ''}`}>{formatDate(task.dueDate)}</span>
                                        </div>
                                    </div>
                                </div>
                                <div className="task-footer">
                                    <span className="task-status-badge">{task.status.replace('_', ' ')}</span>
                                    {isOverdue(task.dueDate, task.status) &&
                                        <span className="overdue-badge">Overdue</span>}
                                </div>
                            </div>
                        ))}
                    </div>

                    <h3 style={{margin: '24px 0 8px', color: '#1a1a1a'}}>Completed</h3>
                    <div className="tasks-grid">
                        {completedTasks.map((task) => (
                            <div key={task.id} className="task-card" onClick={() => setSelectedTask(task)}
                                 style={{cursor: 'pointer', opacity: 0.95}}>
                                <div className="task-card-header">
                                    <div className="task-status-icon">{getStatusIcon(task.status)}</div>
                                    <div style={{display: 'flex', gap: '8px', alignItems: 'center'}}>
                                        <span className="task-priority"
                                              style={{backgroundColor: getPriorityColor(task.priority)}}>{task.priority}</span>
                                        <button onClick={(e) => {
                                            e.stopPropagation();
                                            handleDeleteTask(task.id);
                                        }} className="delete-task-btn" style={{
                                            background: 'none',
                                            border: 'none',
                                            cursor: 'pointer',
                                            color: '#999',
                                            padding: 0
                                        }}><Trash2 size={16}/></button>
                                    </div>
                                </div>

                                <h3 className="task-title">{task.taskName}</h3>
                                <p className="task-description">{task.description || 'No description'}</p>

                                {/* 2. SHOW ASSIGNEE */}
                                {renderAssignee(task)}

                                <div className="task-footer">
                                    <span className="task-status-badge">{task.status.replace('_', ' ')}</span>
                                </div>
                            </div>
                        ))}
                    </div>
                </>
            ) : (
                <div className="tasks-grid">
                    {filteredTasks.map((task) => (
                        <div key={task.id}
                             className={`task-card ${isOverdue(task.dueDate, task.status) ? 'overdue' : ''}`}
                             onClick={() => setSelectedTask(task)} style={{cursor: 'pointer'}}>
                            <div className="task-card-header">
                                <div className="task-status-icon">{getStatusIcon(task.status)}</div>
                                <div style={{display: 'flex', gap: '8px', alignItems: 'center'}}>
                                    <span className="task-priority"
                                          style={{backgroundColor: getPriorityColor(task.priority)}}>{task.priority}</span>
                                    <button onClick={(e) => {
                                        e.stopPropagation();
                                        handleDeleteTask(task.id);
                                    }} className="delete-task-btn" style={{
                                        background: 'none',
                                        border: 'none',
                                        cursor: 'pointer',
                                        color: '#999',
                                        padding: 0
                                    }}><Trash2 size={16}/></button>
                                </div>
                            </div>

                            <h3 className="task-title">{task.taskName}</h3>
                            <p className="task-description">{task.description || 'No description'}</p>

                            {/* 2. SHOW ASSIGNEE */}
                            {renderAssignee(task)}

                            <div className="task-dates">
                                <div className="date-item">
                                    <Calendar size={16}/>
                                    <div className="date-info"><span className="date-label">Start Date</span><span
                                        className="date-value">{formatDate(task.startDate)}</span></div>
                                </div>
                                <div className="date-item">
                                    <Clock size={16}/>
                                    <div className="date-info"><span className="date-label">Deadline</span><span
                                        className={`date-value ${isOverdue(task.dueDate, task.status) ? 'overdue-text' : ''}`}>{formatDate(task.dueDate)}</span>
                                    </div>
                                </div>
                            </div>
                            <div className="task-footer">
                                <span className="task-status-badge">{task.status.replace('_', ' ')}</span>
                                {isOverdue(task.dueDate, task.status) && <span className="overdue-badge">Overdue</span>}
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {selectedTask && (
                <TaskDetailModal
                    task={selectedTask}
                    onClose={() => setSelectedTask(null)}
                    onUpdated={(updated) => {
                        setTasks(prev => prev.map(t => t.id === updated.id ? updated : t));
                        setSelectedTask(null);
                        fetchTasks();
                    }}
                />
            )}
        </div>
    );
};

export default TaskList;
